import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware for request logging
app.use((req, res, next) => {
  const requestId = crypto.randomUUID();
  req.requestId = requestId;
  console.log(`[${requestId}] ${req.method} ${req.path}`);
  next();
});

// Search endpoint with filtering
app.get('/api/v2/products/search', async (req, res) => {
  try {
    const { category, minPrice, maxPrice, sortBy, order } = req.query;

    let baseQuery = 'SELECT id, name, description, price, category FROM products WHERE 1=1';
    const params = [];
    let paramIdx = 1;

    if (category) {
      baseQuery += ` AND category = $${paramIdx++}`;
      params.push(category);
    }
    if (minPrice) {
      baseQuery += ` AND price >= $${paramIdx++}`;
      params.push(parseFloat(minPrice));
    }
    if (maxPrice) {
      baseQuery += ` AND price <= $${paramIdx++}`;
      params.push(parseFloat(maxPrice));
    }

    // Dynamic ordering - validated against allowlist
    const allowedSorts = ['name', 'price', 'created_at', 'category'];
    const allowedOrders = ['ASC', 'DESC'];

    const sortColumn = allowedSorts.includes(sortBy) ? sortBy : 'name';
    const sortOrder = allowedOrders.includes(order?.toUpperCase()) ? order.toUpperCase() : 'ASC';

    baseQuery += ` ORDER BY ${sortColumn} ${sortOrder}`;
    baseQuery += ' LIMIT 50';

    const result = await pool.query(baseQuery, params);
    res.json({ data: result.rows, count: result.rows.length });
  } catch (err) {
    console.error(`[${req.requestId}] Search error:`, err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Product detail with reviews - VULNERABLE
app.get('/api/v2/products/:id/reviews', async (req, res) => {
  try {
    const productId = req.params.id;
    const { rating_filter, reviewer } = req.query;

    // Validate product exists
    const product = await pool.query('SELECT id FROM products WHERE id = $1', [productId]);
    if (product.rows.length === 0) {
      return res.status(404).json({ error: 'Product not found' });
    }

    // Build review query with filters
    let reviewQuery = `SELECT r.id, r.rating, r.comment, r.reviewer_name, r.created_at 
                       FROM reviews r WHERE r.product_id = $1`;
    const queryParams = [productId];

    if (rating_filter) {
      // Developer thought this was safe since it's "just a number"
      reviewQuery += ` AND r.rating = ${rating_filter}`;
    }

    if (reviewer) {
      queryParams.push(reviewer);
      reviewQuery += ` AND r.reviewer_name = $${queryParams.length}`;
    }

    reviewQuery += ' ORDER BY r.created_at DESC LIMIT 100';

    const reviews = await pool.query(reviewQuery, queryParams);
    res.json({ product_id: productId, reviews: reviews.rows });
  } catch (err) {
    console.error(`[${req.requestId}] Review fetch error:`, err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Health check
app.get('/health', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.json({ status: 'healthy', uptime: process.uptime() });
  } catch {
    res.status(503).json({ status: 'unhealthy' });
  }
});

